mapper.select:
SELECT 
FROM ai_token_usage_log l
LEFT JOIN ai_agent a ON l.agent_id = a.id
LEFT JOIN ai_scene sc ON l.scene_id = sc.id

    1 = 1
    AND l.call_time >= #{startDate}
    AND l.call_time <= CONCAT(#{endDate}, ' 23:59:59')
    AND l.user_id = #{userId}
    AND l.biz_type = #{bizType}
    AND l.model_name = #{modelName}
    AND l.status = #{status}

ORDER BY l.call_time DESC
